PTNV_TM_TITLE = "<color=yellow>L\214nh B\181i Nhi\214m V\244<color>: ch\228n nh\227m nhi\214m v\244 r\229i ch\228n NPC, l\214nh b\181i \174\173a b\185n t\237i ngay c\185nh NPC \174\227. C\202p hi\214n t\185i "
PTNV_TM_CUR = "Nhi\214m v\244 \174ang l\181m"
PTNV_TM_NONE = "<color=yellow>L\214nh B\181i Nhi\214m V\244<color>: ch\173a th\202y nhi\214m v\244 n\181o \174ang l\181m (ho\198c \174\183 xong h\213t c\184c b\173\237c c\227 th\211 nh\203n bi\213t). H\183y nh\203n nhi\214m v\244 \235 c\184c NPC trong menu nh\227m."
PTNV_TM_CURTITLE = "<color=yellow>Nhi\214m v\244 \174ang l\181m<color>: ch\228n \174\211 xem b\173\237c hi\214n t\185i v\181 d\222ch chuy\211n t\237i NPC c\199n g\198p."
PTNV_TM_GOTO = "D\222ch chuy\211n t\237i "
